const section = (layer: AcademyLayer, key: string) => `l${layer}-${key}`;
type ConceptDraft = Omit<KnowledgeConcept, "acronym" | "expandedName" | "relatedConceptIds" | "sectionIds" | "synonyms"> & {
  acronym?: string;
  expandedName?: string | null;
  relatedConceptIds?: string[];
  sections: Array<[AcademyLayer, string]>;
  synonyms?: string[];
};
function defineConcept(draft: ConceptDraft): KnowledgeConcept {
  const { sections, ...concept } = draft;
  return {
    ...concept,
    acronym: concept.acronym ?? "",
    expandedName: concept.expandedName ?? null,
    relatedConceptIds: concept.relatedConceptIds ?? [],
    sectionIds: sections.map(([layer, key]) => section(layer, key)),
    synonyms: concept.synonyms ?? [],
  };
}

