export function normalizeKnowledgeSearch(value: string): string {
  return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLocaleLowerCase("es").replace(/[^a-z0-9]+/g, " ").trim();
}

export function searchKnowledge(query: string): KnowledgeConcept[] {
  const needle = normalizeKnowledgeSearch(query);
  if (!needle) return knowledgeConcepts;
  return knowledgeConcepts.filter((concept) => {
    const haystack = normalizeKnowledgeSearch([
      concept.name, concept.acronym, concept.expandedName ?? "", concept.simpleDefinition,
      concept.technicalDefinition, concept.example, ...concept.synonyms,
    ].join(" "));
    return haystack.includes(needle) || needle.split(" ").every((token) => haystack.includes(token));
  });
}

/** Exact, controlled term detection for question tracing. Does not transform HTML. */
export function findConceptIds(text: string): string[] {
  const normalized = normalizeKnowledgeSearch(text);
  return knowledgeConcepts.filter((concept) => {
    const labels = [concept.name, concept.acronym, concept.expandedName ?? "", ...concept.synonyms]
      .filter((label) => label.trim().length >= 2).map(normalizeKnowledgeSearch);
    return labels.some((label) => label && (` ${normalized} `).includes(` ${label} `));
  }).map((concept) => concept.id);
}

